const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Parses the build graph from the raw standard-input text into a map from
 * task name to `{ cost, deps }`, where `deps` is a `Set` of dependency
 * names. Throws a `CliError` (exit 2) on the first malformed line or the
 * first `dep` line that names a task nothing declares.
 */
export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const depEntries = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`line ${lineNo}: expected task <name> <cost>`, 2)
      }
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) {
        throw new CliError(`line ${lineNo}: invalid task name ${name}`, 2)
      }
      if (!COST_RE.test(costStr)) {
        throw new CliError(`line ${lineNo}: cost must be a non-negative integer`, 2)
      }
      if (tasks.has(name)) {
        throw new CliError(`line ${lineNo}: task ${name} is declared twice`, 2)
      }
      tasks.set(name, { cost: parseInt(costStr, 10), deps: new Set() })
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`line ${lineNo}: expected dep <name> <dependency>...`, 2)
      }
      depEntries.push({ name: words[1], deps: words.slice(2) })
    } else {
      throw new CliError(`line ${lineNo}: unknown directive ${directive}`, 2)
    }
  }

  for (const entry of depEntries) {
    if (!tasks.has(entry.name)) throw new CliError(`unknown task ${entry.name}`, 2)
    for (const dep of entry.deps) {
      if (!tasks.has(dep)) throw new CliError(`unknown task ${dep}`, 2)
    }
  }

  for (const entry of depEntries) {
    const deps = tasks.get(entry.name).deps
    for (const dep of entry.deps) deps.add(dep)
  }

  return tasks
}
"}

