{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-4YvhA0/src/graph.js","content":"import { CliError } from './errors.js'

/**
 * Verifies the graph is acyclic. Runs a depth-first search from every task
 * in ascending name order, walking each task's dependencies in ascending
 * name order, and throws a `CliError` (exit 3) describing the first cycle
 * such a search re-enters.
 */
export function checkAcyclic(tasks) {
  const state = new Map() // undefined = unvisited, 'active', 'done'
  const stack = []

  function visit(name) {
    state.set(name, 'active')
    stack.push(name)
    const deps = [...tasks.get(name).deps].sort()
    for (const dep of deps) {
      const depState = state.get(dep)
      if (depState === 'active') {
        const start = stack.indexOf(dep)
        const cycle = stack.slice(start).concat(dep)
        throw new CliError(`cycle: ${cycle.join(' -> ')}`, 3)
      }
      if (depState !== 'done') visit(dep)
    }
    stack.pop()
    state.set(name, 'done')
  }

  for (const name of [...tasks.keys()].sort()) {
    if (state.get(name) !== 'done') visit(name)
  }
}

/** Computes each task's wave, where a task with no dependency is wave 0. */
export function computeDepths(tasks) {
  const depth = new Map()

  function depthOf(name) {
    if (depth.has(name)) return depth.get(name)
    let value = 0
    for (const dep of tasks.get(name).deps) value = Math.max(value, depthOf(dep) + 1)
    depth.set(name, value)
    return value
  }

  for (const name of tasks.keys()) depthOf(name)
  return depth
}

/** Computes each task's start and finish under unlimited workers. */
export function computeTimes(tasks) {
  const start = new Map()
  const finish = new Map()

  function finishOf(name) {
    if (finish.has(name)) return finish.get(name)
    let s = 0
    for (const dep of tasks.get(name).deps) s = Math.max(s, finishOf(dep))
    start.set(name, s)
    const f = s + tasks.get(name).cost
    finish.set(name, f)
    return f
  }

  for (const name of tasks.keys()) finishOf(name)
  return { start, finish }
}

/**
 * Computes each task's priority: the cost of the longest dependency chain
 * beginning at it, counting its own cost and the costs of every task
 * reachable by following dependencies down to one nothing depends on.
 */
export function computePriorities(tasks) {
  const priority = new Map()

  function priorityOf(name) {
    if (priority.has(name)) return priority.get(name)
    let best = 0
    for (const dep of tasks.get(name).deps) best = Math.max(best, priorityOf(dep))
    const value = tasks.get(name).cost + best
    priority.set(name, value)
    return value
  }

  for (const name of tasks.keys()) priorityOf(name)
  return priority
}
"}

