{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-4YvhA0/src/pack.js","content":"import { computePriorities } from './graph.js'

/**
 * Simulates the graph on `workerCount` workers, greedily starting the
 * highest-priority ready task (ties broken by ascending name) on the
 * lowest-indexed free worker whenever both are available, and otherwise
 * advancing to the next instant a worker frees up.
 *
 * Returns an array of per-worker run logs: `{ name, start, finish }[]`.
 */
export function pack(tasks, workerCount) {
  const priority = computePriorities(tasks)
  const names = [...tasks.keys()]
  const remaining = new Set(names)
  const finishTime = new Map()
  const workers = Array.from({ length: workerCount }, () => ({ freeAt: 0, log: [] }))

  let time = 0
  while (remaining.size > 0) {
    let progressed = true
    while (progressed) {
      progressed = false

      let workerIdx = -1
      for (let i = 0; i < workerCount; i++) {
        if (workers[i].freeAt <= time) {
          workerIdx = i
          break
        }
      }
      if (workerIdx === -1) break

      let best = null
      for (const name of remaining) {
        const ready = [...tasks.get(name).deps].every((dep) => finishTime.get(dep) <= time)
        if (!ready) continue
        if (best === null) {
          best = name
        } else {
          const p = priority.get(name)
          const bestP = priority.get(best)
          if (p > bestP || (p === bestP && name < best)) best = name
        }
      }
      if (best === null) break

      const start = time
      const finish = time + tasks.get(best).cost
      workers[workerIdx].log.push({ name: best, start, finish })
      workers[workerIdx].freeAt = finish
      finishTime.set(best, finish)
      remaining.delete(best)
      progressed = true
    }

    if (remaining.size === 0) break
    let next = Infinity
    for (const worker of workers) {
      if (worker.freeAt > time) next = Math.min(next, worker.freeAt)
    }
    time = next
  }

  return workers
}
"}

