 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { CliError } from './errors.js'
import { parseGraph } from './parse.js'
import { checkAcyclic, computeDepths, computeTimes } from './graph.js'
import { pack } from './pack.js'

const USAGE = 'usage: cli.js waves|explain|pack <workers>'
const WORKERS_RE = /^[1-9][0-9]*$/

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      throw new CliError('workers must be a positive integer', 2)
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new CliError(USAGE, 2)
}

function readStdin() {
  return new Promise((resolve, reject) => {
    let data = ''
    process.stdin.setEncoding('utf8')
    process.stdin.on('data', (chunk) => (data += chunk))
    process.stdin.on('end', () => resolve(data))
    process.stdin.on('error', reject)
  })
}

function renderWaves(tasks) {
  const depth = computeDepths(tasks)
  const { finish } = computeTimes(tasks)
  const byWave = new Map()
  let maxDepth = -1
  for (const [name, d] of depth) {
    if (!byWave.has(d)) byWave.set(d, [])
    byWave.get(d).push(name)
    if (d > maxDepth) maxDepth = d
  }

  const lines = []
  for (let k = 0; k <= maxDepth; k++) {
    const names = (byWave.get(k) ?? []).sort()
    lines.push(`wave ${k}: ${names.join(' ')}`)
  }
  const total = finish.size === 0 ? 0 : Math.max(...finish.values())
  lines.push(`total ${total}`)
  return lines
}

function renderExplain(tasks) {
  const depth = computeDepths(tasks)
  const { start, finish } = computeTimes(tasks)
  const lines = []
  for (const name of [...tasks.keys()].sort()) {
    lines.push(`${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`)
  }
  const total = finish.size === 0 ? 0 : Math.max(...finish.values())
  lines.push(`total ${total}`)
  return lines
}

