  const workers = pack(tasks, workerCount)
  const lines = []
  let makespan = 0
  workers.forEach((worker, i) => {
    const runs = worker.log.map((r) => ` ${r.name}@${r.start}-${r.finish}`).join('')
    lines.push(`worker ${i}:${runs}`)
    for (const r of worker.log) makespan = Math.max(makespan, r.finish)
  })
  lines.push(`makespan ${makespan}`)
  return lines
}

async function main() {
  const args = parseArgs(process.argv.slice(2))
  const input = await readStdin()
  const tasks = parseGraph(input)
  checkAcyclic(tasks)

