  if (args.mode === 'waves') lines = renderWaves(tasks)
  else if (args.mode === 'explain') lines = renderExplain(tasks)
  else lines = renderPack(tasks, args.workers)

  process.stdout.write(lines.join('\n') + '\n')
}

main().catch((err) => {
  if (err instanceof CliError) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exitCode = err.code
    return
  }
  throw err
})
"}

